// src/index.ts
var dataset = eu_vat_rates_data_default;
function getRate(code) {
  return dataset.rates[code];
}
function getStandardRate(code) {
  return dataset.rates[code]?.standard;
}
function getAllRates() {
  return dataset.rates;
}
function isEUMember(code) {
  return dataset.rates[code]?.eu_member === true;
}
function isKnownCountry(code) {
  return Object.prototype.hasOwnProperty.call(dataset.rates, code);
}
var dataVersion = dataset.version;
function validateFormat(vatId) {
  if (vatId.length < 2) return false;
  const prefix = vatId.slice(0, 2).toUpperCase();
  const code = prefix === "EL" ? "GR" : prefix;
  const rate = dataset.rates[code];
  if (!rate?.pattern) return false;
  return new RegExp(rate.pattern).test(vatId.toUpperCase());
}
function getFlag(code) {
  const upper = code.toUpperCase();
  if (upper.length !== 2) return "";
  return String.fromCodePoint(
    127462 + upper.charCodeAt(0) - 65,
    127462 + upper.charCodeAt(1) - 65
  );
}
export {
  dataVersion,
  dataset,
  getAllRates,
  getFlag,
  getRate,
  getStandardRate,
  isEUMember,
  isKnownCountry,
  validateFormat
};
